-- Teams (32) - ALL INFERRED --------------------------------------------
-- The Big Bang recorded no teams; it was an individual link-creation event.
-- These country groupings mirror the organiser's own 'Country Stats' tab so the
-- archive has team cards, and every one is flagged confidence = inferred.
insert into teams (campaign_id, slug, name, faction, country,
                   construction_start_date, construction_end_date, links_created,
                   confidence, inference_basis, source_reference, import_batch_id)
