-- Media (342) --------------------------------------------------------------
-- The binaries are NOT in Git (ADR 0002). Each row records source_path + sha256
-- from source-data/MANIFEST.json so the asset stays traceable, and is_uploaded
-- flips to true once scripts/upload-archive-media.mjs pushes it to Storage.
insert into media (campaign_id, role, source_path, source_sha256, bytes,
                   attributed_to, captured_at, captured_at_confidence,
